#!/usr/bin/env node
// Adapt the Clash Verge runtime config for Clash.app. The runtime config is
// already generated by Clash Verge's Script.js and Merge profile script.

const fs = require("node:fs");
const path = require("node:path");
const os = require("node:os");
const YAML = require("yaml");

const ROOT = process.env.CLASH_VERGE_DIR
  || path.join(os.homedir(), "Library/Application Support/io.github.clash-verge-rev.clash-verge-rev");
const SOURCE = path.join(ROOT, "clash-verge.yaml");
const REGISTRY = path.join(ROOT, "profiles.yaml");
const OUTPUT = path.join(ROOT, "exports", "Clash-Workspace.yaml");
const APP_WORKING = path.join(
  os.homedir(),
  "Library/Group Containers/group.com.hako.network/working",
);

function loadYaml(file) {
  return YAML.parse(fs.readFileSync(file, "utf8"));
}

function clone(value) {
  return structuredClone(value);
}

function regex(pattern) {
  if (!pattern) return null;
  const insensitive = pattern.startsWith("(?i)");
  return new RegExp(insensitive ? pattern.slice(4) : pattern, insensitive ? "i" : "");
}

function build() {
  const config = loadYaml(SOURCE);
  const providerNames = {};
  const proxies = [...(config.proxies || [])];

  for (const [providerName, provider] of Object.entries(config["proxy-providers"] || {})) {
    if (provider.type !== "file") {
      throw new Error(`Unsupported proxy provider type for ${providerName}: ${provider.type}`);
    }
    const sourcePath = path.resolve(ROOT, provider.path);
    if (!sourcePath.startsWith(`${ROOT}${path.sep}`)) {
      throw new Error(`Provider path escapes workspace: ${provider.path}`);
    }
    const payload = loadYaml(sourcePath);
    const prefix = provider.override?.["additional-prefix"] || "";
    const exclude = regex(provider["exclude-filter"]);
    const renameMap = new Map((payload.proxies || []).map((proxy) => [
      proxy.name,
      `${prefix}${proxy.name}`,
    ]));
    const names = [];

    for (const sourceProxy of payload.proxies || []) {
      if (exclude?.test(sourceProxy.name)) continue;
      const proxy = clone(sourceProxy);
      proxy.name = renameMap.get(sourceProxy.name);
      for (const key of ["dialer-proxy", "detour"]) {
        if (proxy[key]) proxy[key] = renameMap.get(proxy[key]) || proxy[key];
      }
      if (Array.isArray(proxy.proxies)) {
        proxy.proxies = proxy.proxies.map((name) => renameMap.get(name) || name);
      }
      names.push(proxy.name);
      proxies.push(proxy);
    }
    providerNames[providerName] = names;
  }

  config.proxies = proxies;
  for (const group of config["proxy-groups"] || []) {
    const uses = group.use;
    delete group.use;
    if (!uses) continue;
    const include = regex(group.filter);
    const exclude = regex(group["exclude-filter"]);
    delete group.filter;
    delete group["exclude-filter"];
    const expanded = uses.flatMap((name) => {
      if (!providerNames[name]) throw new Error(`Unknown provider in ${group.name}: ${name}`);
      return providerNames[name];
    }).filter((name) => (!include || include.test(name)) && (!exclude || !exclude.test(name)));
    group.proxies = [...new Set([...(group.proxies || []), ...expanded])];
  }
  delete config["proxy-providers"];

  const registry = loadYaml(REGISTRY);
  const active = (registry.items || []).find((item) => item.uid === registry.current);
  const selected = new Map((active?.selected || []).map((item) => [item.name, item.now]));
  for (const group of config["proxy-groups"] || []) {
    const choices = group.proxies;
    const current = selected.get(group.name);
    if (!current || !Array.isArray(choices) || !choices.includes(current)) continue;
    group.proxies = [current, ...choices.filter((choice) => choice !== current)];
  }

  // Clash.app owns its local controller and listener settings.
  for (const key of [
    "external-controller", "external-controller-unix", "secret",
    "port", "socks-port", "redir-port", "tproxy-port",
  ]) delete config[key];
  config["mixed-port"] = 7890;
  config["allow-lan"] = false;
  return config;
}

function main() {
  const stageGeodata = process.argv.includes("--stage-geodata");
  const outputArg = process.argv.slice(2).find((arg) => !arg.startsWith("--"));
  const output = outputArg ? path.resolve(outputArg) : OUTPUT;
  const config = build();

  fs.mkdirSync(path.dirname(output), { recursive: true });
  fs.writeFileSync(output, YAML.stringify(config, { lineWidth: 120 }), "utf8");

  let staged = "";
  if (stageGeodata) {
    const source = path.join(ROOT, "ASN.mmdb");
    if (!fs.existsSync(APP_WORKING)) throw new Error(`Clash.app working directory not found: ${APP_WORKING}`);
    if (!fs.existsSync(source)) throw new Error(`Workspace ASN database not found: ${source}`);
    fs.copyFileSync(source, path.join(APP_WORKING, "ASN.mmdb"));
    staged = `\n  ASN geodata: ${path.join(APP_WORKING, "ASN.mmdb")}`;
  }

  console.log(`Built ${output}`);
  console.log(`  nodes: ${config.proxies.length}`);
  console.log(`  groups: ${config["proxy-groups"].length}`);
  console.log(`  rule providers: ${Object.keys(config["rule-providers"] || {}).length}`);
  console.log(`  rules: ${config.rules.length}${staged}`);
}

main();
